    # Create adjacency list for flights
    graph = defaultdict(list)
    for d, f, t, c in flights:
        if f == 0:
            graph[t].append((d, c))
        elif t == 0:
            graph[f].append((d, c))

    # Dijkstra's algorithm to find the minimum cost to reach each city from Metropolis
    def dijkstra(start):
        min_cost = {i: float('inf') for i in range(n + 1)}
