from collections import defaultdict

def minimum_cost_to_gather_jury(n, m, k, flights):
    # Create adjacency list for flights
    outgoing = defaultdict(list)
    incoming = defaultdict(list)

    for d, f, t, c in flights:
        if f == 0:
            outgoing[d].append((t, c))
        elif t == 0:
            incoming[d].append((f, c))

    # Sort flights by day
    outgoing = dict(sorted(outgoing.items()))
    incoming = dict(sorted(incoming.items()))

    # Initialize DP table
    dp = [float('inf')] * (n + 1)
    dp[0] = 0

    # Priority queue for managing flights
    pq = [(0, 0)]  # (cost, day)

    for day in range(1, max(max(outgoing.keys(), default=0), max(incoming.keys(), default=0)) + 1):
        # Process outgoing flights
        if day in outgoing:
            for t, c in outgoing[day]:
                heapq.heappush(pq, (dp[t] + c, day))

        # Process incoming flights
        if day in incoming:
            for f, c in incoming[day]:
                dp[f] = min(dp[f], dp[0] + c)

        # Update dp for current day
        while pq and pq[0][1] < day:
            cost, _ = heapq.heappop(pq)
            for t in range(1, n + 1):
                dp[t] = min(dp[t], cost)

    # Check if it's possible to gather in Metropolis for k days
    if dp[0] == float('inf'):
        return -1

    # Calculate total cost
    total_cost = dp[0] * k

    # Check if it's possible to send back
    for day in range(1, max(incoming.keys(), default=0) + 1):
        if day in incoming:
            for f, c in incoming[day]:
                if dp[f] + c < dp[0]:
                    return -1

    return total_cost

